import { phase } from './homeMotion.js';

export const COAST_LOOP = { out: 2380, in: 3885 };

// Each visible property has one continuous envelope. Their overlap avoids
// stopping at greyscale, then accelerating through another shader threshold.
const envelope = (time, start, end) => {
  const p = phase(time, start, end);
  return p * p * p * (p * (p * 6 - 15) + 10);
};

export function coastLoopAppearance(stage, elapsed) {
  if (stage === 'out') return {
    lines: 1 - envelope(elapsed, 1120, COAST_LOOP.out),
    depth: 1 - envelope(elapsed, 420, 1960),
    colour: 1 - envelope(elapsed, 0, 1330),
  };
  if (stage === 'in') return {
    lines: envelope(elapsed, 0, 2205),
    depth: envelope(elapsed, 1365, 3325),
    colour: envelope(elapsed, 2345, COAST_LOOP.in),
  };
  const value = stage === 'idle' ? 1 : 0;
  return { lines: value, depth: value, colour: value };
}
