.travel-orbit-controls .is-next::before { clip-path: polygon(62.5% 4.7%,95.3% 50%,62.5% 95.3%,39.1% 76.6%,57.8% 50%,39.1% 23.4%); }
.travel-orbit-controls svg { width: 104px; height: 104px; filter: drop-shadow(0 3px 6px rgba(20,26,30,.36)); transition: transform 260ms cubic-bezier(.22,1,.36,1); }
.travel-orbit-controls svg path { stroke: rgba(255,255,255,.44); stroke-width: .8; stroke-linejoin: round; }
