  .travel-orbit-controls .is-next:hover svg,.travel-orbit-controls .is-next:hover::before { transform: translateX(11px); }
}
@media (max-width:760px) {
  .travel-orbit-photo { height: min(350px, 52dvh); }
  .travel-orbit-controls button { width: 44px; }
  .travel-orbit-controls svg,.travel-orbit-controls button::before { width: 60px; height: 60px; }
}
@media (prefers-reduced-motion:reduce) { .travel-orbit-controls button,.travel-orbit-controls svg,.travel-orbit-controls button::before { transition: none; } }
