<template>
  <div class="gallery-building-mark" :class="{'is-interactive':interactive}">
    <div ref="host" class="gallery-model-canvas" role="img" aria-label="Architectural model of The View Gallery" :tabindex="interactive ? 0 : undefined" @keydown="onKey">
      <img v-if="failed" src="/assets/img/projects/gallery-experience/building-light.webp?v=20260925" alt="The Gallery building" />
    </div>
    <div v-if="interactive && !failed" class="gallery-model-tools" role="group" aria-label="Model controls">
      <button type="button" :aria-pressed="interior" @click="interior = !interior">{{ interior ? 'Replace roof' : 'Look inside' }}</button>
      <button type="button" aria-label="Reset model view" @click="resetView"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 7a6.5 6.5 0 1 1-.1 6M4 3v4h4"/></svg></button>
    </div>
  </div>
</template>
<script>
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { createGalleryArchitecturalModel } from '../../utils/galleryArchitecturalModel';
export default {
  name:'GalleryBuildingMark',
  props:{active:Boolean,interactive:Boolean,detailed:Boolean,dark:{type:Boolean,default:null}},
  data:()=>({failed:false,interior:false}),
  mounted(){
    this._yaw=-.2;this._roof=0;
    this._motion=window.matchMedia('(prefers-reduced-motion: reduce)');
    this._visibility=new IntersectionObserver(([entry])=>{this._visible=entry.isIntersecting;if(this._visible){this.initModel();this.animate();}else cancelAnimationFrame(this._frame);},{rootMargin:'100px'});
    this._visibility.observe(this.$el);
    this._resize=new ResizeObserver(this.resizeModel);this._resize.observe(this.$refs.host);
    window.addEventListener('theme-change',this.syncTheme);
    this._pageVisibility=()=>{if(document.hidden)cancelAnimationFrame(this._frame);else if(this._visible)this.animate();};document.addEventListener('visibilitychange',this._pageVisibility);
  },
  beforeUnmount(){
    this._visibility?.disconnect();this._resize?.disconnect();cancelAnimationFrame(this._frame);
    window.removeEventListener('theme-change',this.syncTheme);document.removeEventListener('visibilitychange',this._pageVisibility);
    this._controls?.dispose();this._architecture?.dispose();Object.values(this._materials||{}).forEach(m=>m.dispose());this._renderer?.dispose();
  },
  watch:{dark(){this.syncTheme();},active(){this.animate();},interior(){this.animate();},interactive(value){if(this._controls)this._controls.enabled=value;this.$refs.host.style.touchAction=value?'none':'pan-y';this.interior=value;this.animate();}},
  methods:{
    initModel(){
      if(this._renderer||this.failed)return;
      try{
        this._renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'low-power'});
        this._renderer.setPixelRatio(Math.min(devicePixelRatio,2));this._renderer.setClearColor(0,0);this._renderer.outputColorSpace=THREE.SRGBColorSpace;
        this._renderer.domElement.setAttribute('aria-hidden','true');this.$refs.host.appendChild(this._renderer.domElement);
        this._scene=new THREE.Scene();this._scene.add(new THREE.HemisphereLight(0xffffff,0x91877b,2.4));
        const sun=new THREE.DirectionalLight(0xffffff,2.3);sun.position.set(-25,60,40);this._scene.add(sun);
        this._materials=Object.fromEntries(['edge','floor','stone','paper','metal'].map(key=>[key,new THREE.MeshStandardMaterial({roughness:.85,metalness:0})]));
        this._architecture=createGalleryArchitecturalModel(this._materials,()=>this.renderModel(),this.detailed);
        const center=new THREE.Box3().setFromObject(this._architecture.root).getCenter(new THREE.Vector3());this._architecture.root.position.copy(center).negate();
        this._model=new THREE.Group();this._model.add(this._architecture.root);this._scene.add(this._model);
        this._camera=new THREE.OrthographicCamera(-40,40,30,-30,.1,400);this._camera.position.set(60,68,90);this._camera.lookAt(0,0,0);
        this._controls=new OrbitControls(this._camera,this.$refs.host);this._controls.enabled=this.interactive;this.$refs.host.style.touchAction=this.interactive?'none':'pan-y';this._controls.enableDamping=!this._motion.matches;
        this._controls.dampingFactor=.12;this._controls.rotateSpeed=.65;this._controls.zoomSpeed=.8;this._controls.panSpeed=.8;
        this._controls.minPolarAngle=.03;this._controls.maxPolarAngle=Math.PI-.03;this._controls.minZoom=.65;this._controls.maxZoom=5;
        this._controls.addEventListener('start',this.onModelInteraction);this._controls.addEventListener('change',this.renderModel);
        this._controls.saveState();this.interior=this.interactive;this.syncTheme();this.resizeModel();
      }catch{this.failed=true;}
    },
    syncTheme(){
      if(!this._materials)return;const dark=this.dark ?? document.body.classList.contains('dark-mode');
      const colours=dark?{edge:0x929389,floor:0xb7b4a6,stone:0xd0cbbb,paper:0xe0dacc,metal:0x56574f}:{edge:0xbcb8a9,floor:0xd2cbbb,stone:0xe0d9c9,paper:0xebe5d7,metal:0x636258};
      Object.entries(colours).forEach(([key,value])=>this._materials[key].color.setHex(value));
      this._architecture.roof.children.forEach(mesh=>mesh.material.color.copy(this._materials.stone.color));this.renderModel();
    },
    resizeModel(){if(!this._renderer)return;const w=this.$refs.host.clientWidth,h=this.$refs.host.clientHeight;if(!w||!h)return;this._renderer.setSize(w,h);const span=Math.max(46,62*h/w);Object.assign(this._camera,{top:span/2,bottom:-span/2,left:-span*w/h/2,right:span*w/h/2});this._camera.updateProjectionMatrix();this.renderModel();},
    renderModel(){if(this._renderer&&this._scene)this._renderer.render(this._scene,this._camera);},
    animate(){
      cancelAnimationFrame(this._frame);if(!this._renderer||!this._visible||document.hidden)return;
      const tick=()=>{
        const factor=this._motion.matches?1:.12,target=-.2+(this.active&&!this._motion.matches?.12:0);
        this._yaw+=(target-this._yaw)*factor;this._model.rotation.y=this._yaw;
        this._roof+=((this.interior?1:0)-this._roof)*factor;
        this._architecture.roof.position.y=this._roof*3;this._architecture.roof.visible=this._roof<.998;
        this._architecture.roof.children.forEach(mesh=>{mesh.material.opacity=1-this._roof;mesh.material.depthWrite=this._roof<.01;});
        this.advanceReset();const moving=this._controls.update();this.renderModel();
        if(this.interactive||moving||Math.abs(target-this._yaw)>.0002||Math.abs((this.interior?1:0)-this._roof)>.0002)this._frame=requestAnimationFrame(tick);
      };tick();
    },
    cancelReset(){if(!this._resetMotion)return;this._controls.enableDamping=this._resetMotion.damping;this._resetMotion=null;},
    onModelInteraction(){this.cancelReset();this.animate();},
    resetView(){
      if(!this._controls)return;
      this.cancelReset();
      if(this._motion.matches){this._controls.reset();this.animate();return;}
      const controls=this._controls,camera=this._camera;
      const position=camera.position.clone(),target=controls.target.clone(),zoom=camera.zoom,damping=controls.enableDamping;
      // Clear residual drag momentum before taking over the orbit.
      controls.enableDamping=false;controls.update();
      camera.position.copy(position);controls.target.copy(target);camera.zoom=zoom;camera.updateProjectionMatrix();controls.update();
      const from=new THREE.Spherical().setFromVector3(position.clone().sub(target));
      const to=new THREE.Spherical().setFromVector3(controls.position0.clone().sub(controls.target0));
      to.theta=from.theta+Math.atan2(Math.sin(to.theta-from.theta),Math.cos(to.theta-from.theta));
      this._resetMotion={start:performance.now(),from,to,target,endTarget:controls.target0.clone(),zoom,endZoom:controls.zoom0,damping};
      this.animate();
    },
    advanceReset(){
      const motion=this._resetMotion;if(!motion)return;
      const progress=Math.min(1,(performance.now()-motion.start)/560),ease=1-Math.pow(1-progress,3);
      const orbit=new THREE.Spherical(THREE.MathUtils.lerp(motion.from.radius,motion.to.radius,ease),THREE.MathUtils.lerp(motion.from.phi,motion.to.phi,ease),THREE.MathUtils.lerp(motion.from.theta,motion.to.theta,ease));
      this._controls.target.lerpVectors(motion.target,motion.endTarget,ease);
      this._camera.position.copy(this._controls.target).add(new THREE.Vector3().setFromSpherical(orbit));
      this._camera.zoom=THREE.MathUtils.lerp(motion.zoom,motion.endZoom,ease);this._camera.updateProjectionMatrix();
      if(progress===1)this.cancelReset();
    },
    onKey(event){
      if(!this.interactive||!this._controls)return;
      const delta={ArrowLeft:[-.15,0],ArrowRight:[.15,0],ArrowUp:[0,-.15],ArrowDown:[0,.15]}[event.key];
      if(delta){event.preventDefault();event.stopPropagation();this.cancelReset();const offset=this._camera.position.clone().sub(this._controls.target),spherical=new THREE.Spherical().setFromVector3(offset);spherical.theta+=delta[0];spherical.phi=THREE.MathUtils.clamp(spherical.phi+delta[1],.03,Math.PI-.03);this._camera.position.copy(this._controls.target).add(new THREE.Vector3().setFromSpherical(spherical));this.animate();}
      else if(['+','=','-','0'].includes(event.key)){event.preventDefault();if(event.key==='0')this.resetView();else{this.cancelReset();this._camera.zoom=THREE.MathUtils.clamp(this._camera.zoom*(event.key==='-'?.9:1.1),.65,5);this._camera.updateProjectionMatrix();this.renderModel();}}
    },
  },
};
</script>
<style scoped>
.gallery-building-mark{display:block;position:relative;width:100%;height:100%;overflow:hidden;}
.gallery-model-canvas{width:100%;height:100%;}.gallery-model-canvas :deep(canvas){display:block;width:100%;height:100%;pointer-events:none;}
.gallery-building-mark img{display:block;width:100%;height:100%;object-fit:contain;}
.is-interactive .gallery-model-canvas{cursor:var(--site-black-grab-cursor,grab);touch-action:none;}.is-interactive .gallery-model-canvas:active{cursor:var(--site-black-grabbing-cursor,grabbing);}
.gallery-model-tools{position:absolute;right:14px;bottom:14px;display:flex;align-items:center;gap:6px;color:var(--site-text-primary,#36332f);}
.gallery-model-tools button{display:grid;place-items:center;min-height:34px;padding:0 12px;background:color-mix(in srgb,var(--site-bg,#fff) 88%,transparent);border:0;border-radius:3px;color:inherit;font:12px/1 'Quattrocento Sans',sans-serif;cursor:var(--site-interactive-cursor,pointer);}
.gallery-model-tools button:last-child{width:34px;padding:0;}.gallery-model-tools svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.3;stroke-linecap:round;stroke-linejoin:round;}
.gallery-model-tools button:focus-visible,.gallery-model-canvas:focus-visible{outline:1px solid currentColor;outline-offset:-2px;}
@media(hover:hover){.gallery-model-tools button:hover{background:var(--site-bg,#fff);}}
</style>
